    crate::bounded_output::with_limit(usize::MAX, || {
        let mut budget = ReplayBudget::new();
        let mut frames = fresh_receiving(function, &mut budget).unwrap();
        for _ in HELD_TARGETS.into_iter().skip(1) {
            fill_held(&mut frames, function);
